// fixed
export function Inbox(props: { title: string; messages: Message[] }) {
  const open = signal(false)
  return (
    <section>
      <h2 onClick={() => open.set(!open())}>{props.title}</h2>
      <ul>
        <For each={props.messages} by={(m) => m.id}>
          {(m) => <li>{m.subject}</li>}
        </For>
      </ul>
    </section>
  )
}

