import { render, screen, fireEvent } from '@testing-library/react'

let totalRenders = 0
function Total({ qty }: { qty: number }) {
  totalRenders++
  return <output>Total: {qty * 12}</output>
}

function Shop() {
  const [qty] = useState(1)
  const [dark, setDark] = useState(false)
  return (
    <div className={dark ? 'dark' : 'light'}>
      <button onClick={() => setDark((d) => !d)}>Dark mode</button>
      <Total qty={qty} />
    </div>
  )
}

test('dark mode re-renders Total', () => {
  render(<Shop />)
  const before = totalRenders
  fireEvent.click(screen.getByRole('button', { name: 'Dark mode' }))
  expect(totalRenders).toBe(before + 1) // memo() would stop it
})

