import { signal, effect } from '@pyreon/reactivity'
import { expectEffect } from '@pyreon/testing'

test('dark mode does not re-run the total', () => {
  const qty = signal(1)
  const dark = signal(false)
  const total = effect(() => {
    document.title = `Total: ${qty() * 12}`
  })
  expectEffect(total).toReRunWhen(() => qty.set(2))
  expectEffect(total).notToReRunWhen(() => dark.set(true))
})

