import { expectEffect, expectSignal } from '@pyreon/testing'
import { signal, computed, effect } from '@pyreon/reactivity'

test('a theme switch does not re-run the cart log', () => {
  const qty = signal(1)
  const theme = signal('light')
  const log = effect(() => { qty() })
  expectEffect(log).toReRunWhen(() => qty.set(2))
  expectEffect(log).notToReRunWhen(() => theme.set('dark'))
})

test('total recomputes once per change', () => {
  const qty = signal(1)
  const total = computed(() => qty() * 12)
  total() // first computation counts as 1
  qty.set(3)
  expectSignal(total).toHaveRecomputedTimes(2)
})
